from godlib import *
d=dict(kicker='THE ALL-PERVADING · ON ŚEṢA · AND THE TEN DESCENTS',
cov=covart('Viṣṇu reclining on the serpent Śeṣa on the ocean of milk, Lakṣmī at his feet, Garuḍa above',g(240,190,1.6,sheshashayi())+g(400,90,.8,garuda())),
cap='The preserver',how='Who Viṣṇu is: the Vedic god of <b>three strides</b>, his conch, discus, mace and lotus, <b>Vaikuṇṭha</b>, his forms and avatāras, <b>four great stories</b>, worship, temples and the teachers of Vaiṣṇavism.',
desc='Who is Viṣṇu? An illustrated guide: his name and Vedic three strides, his four emblems, Vaikuṇṭha, Śeṣa and Garuḍa, Lakṣmī, his forms and avatāras, the stories of Vāmana, Gajendra, Madhu and Kaiṭabha and the Viśvarūpa, worship, temples and Vaiṣṇava traditions.',
fw=['Viṣṇu is the god who keeps the world going: <b>the preserver</b>, who rests on the cosmic serpent on the ocean of milk and comes down, age after age, whenever goodness is in danger.','This guide answers the question <b>who is Viṣṇu?</b> from the Veda to the temples: his name, his emblems, his home and companions, his forms, four of his stories, how he is worshipped and the teachers who made his path.','His ten descents each have their own guide in our '+L('/vishnu/dashavatara/','Daśāvatāra')+' series.'],
fwtk=[('z','He sleeps on a snake?'),('b','Rests, Zappy. And even resting, he holds the world.')],
glance=[('Name','Viṣṇu, “the all-pervading”'),('Other names','Nārāyaṇa, Hari, Vāsudeva, Keśava, Govinda'),('Role','Preserver in the Trimūrti; Supreme God for Vaiṣṇavas'),('Home','Vaikuṇṭha; the ocean of milk'),('Consort','Lakṣmī (with Bhūdevī)'),('Mount','Garuḍa'),('Bed','The serpent Śeṣa (Ananta)'),('Emblems','Conch, discus, mace, lotus'),('Descents','Ten main avatāras; more in the Bhāgavata'),('Great days','Vaikuṇṭha Ekādaśī, Ekādaśīs, Janmāṣṭamī, Rāma Navamī')],
gfig=row('Viṣṇu’s emblems: conch, discus, mace and lotus, and Garuḍa',[(conch(),1.2),(discus(),1.2),(mace(),1.2),(lotus(),1.2),(garuda(),.7)],'#e3eaf3'),gtk=[('z','Four things in four hands!'),('b','Each means something, Zappy.')],gk='The <b>preserver</b>.',
pages=[
('r','name','THE NAME AND THE VEDA','The god of three strides',S('A giant figure striding across earth, sky and heaven',g(120,180,.6,vamana())+g(330,185,1.6,god('#3a6ab8'))+'<path d="M40 180 H520 M40 120 H520 M40 60 H520" stroke="#8a9aae" stroke-dasharray="6 6"/>'+lab(520,175,'earth',10)+lab(520,115,'sky',10)+lab(520,55,'heaven',10),'#dfe9f6'),
 ['<b>The name.</b> Viṣṇu is usually explained as “the all-pervading”, from a root meaning to spread or enter.','<b>In the Ṛgveda.</b> Only five of its 1,028 hymns are addressed to him, but he is the friend of Indra and the god of <b>three strides</b> who measures out earth, sky and heaven.','<b>Rise.</b> In later times he merged with Nārāyaṇa, the cosmic person, and Vāsudeva-Kṛṣṇa, and became for millions the Supreme God.','<b>Other names.</b> Hari (“who takes away”), Nārāyaṇa, Keśava, Govinda: a thousand of them in the '+L('/vishnu/vishnu-sahasranama/','Viṣṇu Sahasranāma')+'.'],
 [('z','Only five hymns at the start?'),('b','Small seeds, Zappy. Look at the tree now.')],'The god of <b>three strides</b>.'),
('c','look','HIS EMBLEMS','Conch, discus, mace, lotus',S('A standing four-armed Viṣṇu with labels for each emblem',g(280,190,2.1,vishnu())+''.join(lab(x,y,t,11) for x,y,t in ((120,40,'conch Pāñcajanya'),(440,40,'discus Sudarśana'),(120,120,'mace Kaumodakī'),(440,120,'lotus'))),'#e3eaf3',200),
 [('🐚','Conch','Pāñcajanya: its sound is the call of dharma and the first sound of creation.'),('☸️','Discus','Sudarśana, “beautiful to see”: the mind, swift as light, that cuts ignorance.'),('🔨','Mace','Kaumodakī: strength, knowledge and the power of time.'),('🪷','Lotus','Purity and unfolding: beauty untouched by the mud it grows in.'),('💙','Dark-blue body','The colour of the sky and the deep sea: vast and infinite.'),('💎','Kaustubha and Śrīvatsa','The jewel on his chest and the mark of Lakṣmī there; a garland of forest flowers, yellow silk.')],
 [('z','Why blue?'),('b','Like the sky and the ocean, Zappy: no edge to him.')],'Four hands, <b>four gifts</b>.'),
('r','vaikuntha','VAIKUṆṬHA AND THE MILK OCEAN','Śeṣa, Garuḍa and Lakṣmī',S('Viṣṇu reclining on Śeṣa on the ocean, Brahmā on a lotus from his navel, Lakṣmī at his feet',g(280,180,2,sheshashayi())+g(470,90,.7,garuda()),'#dfe9f6'),
 ['<b>Anantaśayana.</b> Between ages he reclines on <b>Śeṣa</b> (Ananta, “endless”), the thousand-headed serpent, on the ocean of milk.','<b>Creation.</b> From his navel rises a lotus, and on it Brahmā, who creates the world.','<b>Lakṣmī.</b> His consort sits at his feet or on his chest; read our '+L('/devi/lakshmi/','Lakṣmī')+' guide.','<b>Garuḍa.</b> The eagle king is his mount and banner; read our '+L('/vishnu/garuda-purana/','Garuḍa Purāṇa')+' series.','<b>Vaikuṇṭha.</b> His heaven, the goal of the devotee: its doors open on '+L('/festivals/vaikuntha-ekadashi/','Vaikuṇṭha Ekādaśī')+'.'],
 [('z','Brahmā comes out of his navel?'),('b','On a lotus stalk, Zappy. Creation begins in Viṣṇu.')],'Rest that <b>holds the world</b>.'),
('c','forms','HIS FORMS','From cosmic to childlike',row('Four forms: reclining, standing with a raised hand, a giant cosmic form, and a baby on a leaf',[(sheshashayi(),.7),(vishnu(),1),(god('#3a6ab8'),1.4),(krishna_child(),1)],'#e3eaf3',190,['Raṅganātha','Veṅkaṭeśa','Viśvarūpa','on the banyan leaf']),
 [('🛏️','Anantaśayana','Reclining on Śeṣa: Raṅganātha of Śrīraṅgam, Padmanābha of Thiruvananthapuram.'),('🧍','Standing','Veṅkaṭeśa of Tirumala, Viṭṭhala of Paṇḍharpur, Jagannātha of Purī.'),('🔱','Nārāyaṇa','The cosmic person of the Puruṣa Sūkta; read our '+L('/vishnu/purusha-suktam/','Puruṣa Sūktam')+'.'),('🌌','Viśvarūpa','The universal form shown to Arjuna in the Gītā.'),('🍃','Vaṭapatraśāyī','The baby floating on a banyan leaf at the end of the world, sucking his toe.'),('🐟','The avatāras','Ten main descents, from the fish to Kalki; the Bhāgavata lists more.')],
 [('z','A baby on a leaf in the flood?'),('b','At the end of everything, Zappy, he is still there, playing.')],'Cosmic <b>and childlike</b>.'),
('c','avataras','THE TEN DESCENTS','Daśāvatāra',S('Ten small symbols in a row: fish, tortoise, boar, man-lion, dwarf, axe, bow, plough, flute, horse',''.join(lab(30+k*55,100,t,10) for k,t in enumerate(['Matsya','Kūrma','Varāha','Narasiṃha','Vāmana','Paraśurāma','Rāma','Balarāma','Kṛṣṇa','Kalki']))+''.join(f'<circle cx="{30+k*55}" cy="70" r="18" fill="#3a6ab8" stroke="#111" stroke-width="2"/>' for k in range(10)),'#e3eaf3',150),
 [('📜','Why he comes','In the Gītā he says he is born age after age to protect the good and restore dharma.'),('🐟','The first four','Matsya, Kūrma, Varāha, Narasiṃha: '+L('/vishnu/dashavatara/','our series')+'.'),('🏹','Rāma and Kṛṣṇa','The most loved: read '+L('/vishnu/rama/','Rāma')+' and '+L('/vishnu/krishna/','Kṛṣṇa')+'.'),('🐎','Kalki','The one still to come, at the end of this age.')],
 [('z','Ten exactly?'),('b','The famous list is ten, Zappy. Some lists differ, and the Bhāgavata gives more.')],'He <b>comes down</b>.','The word avatāra means “descent”. Viṣṇu descends in a form suited to each crisis.'),
('s','vamana','STORY 1 · THE THREE STEPS','Vāmana and Bali',strip('Three panels: a dwarf boy asking a king for land; the boy growing huge; one foot placed on the king’s head',[panel([(vamana(),.8),(person('#8e1f17'),.8)],'#fff3cf'),panel([(god('#3a6ab8'),1.3)],'#dfe9f6'),panel([(person('#8e1f17',seat=True),.8)],'#e3f5e9')],['three steps of land','he grows','the third step']),'From the Bhāgavata Purāṇa.',
 ['The generous demon-king <b>Bali</b> had won the three worlds.','Viṣṇu came as <b>Vāmana</b>, a dwarf boy, and asked for just three steps of land.','Bali agreed. The boy grew vast: one step covered the earth, the second the heavens.','Nothing was left; Bali offered his own head for the third step.','Viṣṇu sent him to the netherworld as its king and became his guard. Read our '+L('/vishnu/dashavatara/vamana/','Vāmana')+' guide.'],
 [('z','Bali lost everything?'),('b','And gained Viṣṇu at his door, Zappy.')],'Three <b>steps</b>.'),
('s','gajendra','STORY 2 · GAJENDRA','The elephant who called',strip('Three panels: an elephant in a lake seized by a crocodile; the elephant raising a lotus; Viṣṇu on Garuḍa throwing the discus',[panel([(elephant(howdah=False),.6)],'#dfe9f6'),panel([(elephant(howdah=False),.6),(lotus(),.6)],'#e3f5e9'),panel([(garuda(),.6),(discus(),.6)],'#fff3cf')],['seized','the cry','rescued']),'From the Bhāgavata Purāṇa, Book 8.',
 ['<b>Gajendra</b>, king of elephants, went to bathe in a lake.','A crocodile seized his leg. They struggled for a very long time; the elephant’s strength failed.','At last he gave up his pride, raised a lotus in his trunk and called on the Lord.','Viṣṇu came at once on Garuḍa and cut the crocodile with his discus.','The elephant was freed. The story is told as the power of surrender. (Gajendra Mokṣa.)'],
 [('z','Why didn’t he call earlier?'),('b','He was trying alone, Zappy. The story says: call.')],'<b>Call</b>, and he comes.'),
('s','madhu','STORY 3 · MADHU AND KAIṬABHA','Before creation',strip('Three panels: Viṣṇu asleep on Śeṣa with Brahmā on the lotus; two demons threatening Brahmā; Viṣṇu fighting them on his thighs',[panel([(sheshashayi(),.5)],'#dfe9f6'),panel([(demon(),.6),(demon('#6a3a2a'),.6)],'#20243a'),panel([(god('#3a6ab8'),.8)],'#e3eaf3')],['the sleep','two demons','the battle']),'From the Devī Māhātmya, chapter 1, and the Purāṇas.',
 ['Before creation Viṣṇu slept on Śeṣa, and Brahmā sat on the lotus from his navel.','Two demons, <b>Madhu and Kaiṭabha</b>, born of his earwax, rose to kill Brahmā.','Brahmā praised Yoganidrā, the Devī as Viṣṇu’s sleep, and she left him.','Viṣṇu woke and fought them for five thousand years; at last they asked to be killed where there was no water.','He killed them on his thighs. Read our '+L('/devi/devi-mahatmya/','Devī Māhātmya')+' series.'],
 [('z','Even Viṣṇu needed the Devī to wake him?'),('b','The two work together, Zappy.')],'He <b>wakes</b> to protect.'),
('r','visvarupa','STORY 4 · THE UNIVERSAL FORM','Chapter 11 of the Gītā',S('A vast form filling the sky above a tiny chariot',g(280,200,2.4,vishnu())+g(470,190,.5,person('#c0392b')),'#20243a',200),
 ['<b>The request.</b> On the battlefield Arjuna asks Kṛṣṇa to show his true form.','<b>The vision.</b> Given divine sight, he sees all worlds, gods and beings in one body, and time devouring the armies.','<b>Fear and love.</b> Arjuna trembles and begs to see his friend’s gentle form again.','<b>Read it.</b> Our '+L('/vishnu/bhagavad-gita/chapter-11/','Gītā chapter 11')+', verse by verse.'],
 [('z','He wanted his friend back?'),('b','Infinite is hard to love, Zappy. So God comes as a friend.')],'Infinite, yet a <b>friend</b>.'),
('r','worship','HOW HE IS WORSHIPPED','Ekādaśī, tulasī and the name',row('Tulasī plant, a lamp, a conch and a devotee chanting',[(tulasi(),1),(lamp(),1),(conch(),1.1),(namaste('#1d4f8a'),1)],'#e3eaf3'),
 ['<b>Ekādaśī.</b> The eleventh lunar day, twice a month, is his fast; read our '+L('/festivals/ekadashi/','Ekādaśī')+' guides.','<b>Tulasī.</b> The holy basil is dearest to him; no worship is complete without a leaf. Read our '+L('/festivals/kartika/tulasi/','Tulasī')+' guide.','<b>The name.</b> Chanting his names, especially the '+L('/vishnu/vishnu-sahasranama/','thousand names')+', is the simplest worship.','<b>Mantras.</b> Oṃ Namo Nārāyaṇāya and Oṃ Namo Bhagavate Vāsudevāya are the best known.','<b>Morning.</b> Many begin the day with the '+L('/vishnu/shantakaram/','Śāntākāram')+' verse.'],
 [('z','Just saying his name?'),('b','The Kali age’s easiest path, Zappy, so the teachers say.')],'Chant <b>the name</b>.'),
('r','temples','HIS GREAT TEMPLES','From Tirumala to Badrīnāth',row('Temple towers in a row',[(palace(),1),(sheshashayi(),.5),(palace(),1),(mountain('#9fb3c8',True),.5)],'#e3eaf3'),
 ['<b>Tirumala.</b> Veṅkaṭeśvara on the seven hills; read our '+L('/temples-of-india/andhra-pradesh/tirumala/','Tirumala')+' guide and the '+L('/vishnu/venkatesa-suprabhatam/','Suprabhātam')+'.','<b>Śrīraṅgam.</b> The reclining Raṅganātha, first of the 108 Divya Deśams; read our '+L('/temples-of-india/triranga/','Triraṅga')+' series.','<b>The four dhāms.</b> Badrīnāth, Purī, Dvārakā, with Rāmeśvaram: our '+L('/temples-of-india/char-dham/','Char Dham')+'.','<b>Karnataka.</b> '+L('/temples-of-india/around-mysuru/melukote/','Mēlukōṭe')+' and '+L('/tulunadu/temples/udupi-srikrishna/','Udupi')+'.'],
 [('z','108 Divya Deśams?'),('b','The temples sung by the Āḻvārs, Zappy.')],'Viṣṇu <b>across India</b>.'),
('r','traditions','HIS DEVOTEES AND TEACHERS','Āḻvārs and ācāryas',row('Three teachers: one with a triple staff, one with a single staff, one singing',[(sage('#ff8c1a'),1),(sage('#fff'),1),(namaste('#1d4f8a'),1)],'#fde9c8',190,['Rāmānuja','Madhva','Āḻvārs']),
 ['<b>The Āḻvārs.</b> Twelve Tamil poet-saints whose hymns spread love of Viṣṇu across the south.','<b>Rāmānuja.</b> The teacher of Viśiṣṭādvaita, “qualified non-dualism”, who lived at Mēlukōṭe for years.','<b>Madhva.</b> The Dvaita teacher of Udupi; the Haridāsas of Karnataka, Purandara and Kanaka, sang in his tradition.','<b>The north.</b> Nimbārka, Vallabha and Caitanya, with their love of Kṛṣṇa; Rāmānanda and Tulsīdās, of Rāma.'],
 [('z','So many schools!'),('b','One Viṣṇu, many ways to love him, Zappy.')],'Many <b>teachers</b>.'),
('r','meaning','WHAT VIṢṆU TEACHES','Preservation and care',S('A hand holding up a small earth, protected',g(280,180,1.6,god('#3a6ab8'))+'<circle cx="280" cy="40" r="22" fill="#5a8ab8" stroke="#111"/>','#dfe9f6'),
 ['<b>Preserving.</b> He keeps the world going, quietly and constantly. Many read his rest on Śeṣa as calm in the middle of action. (Interpretation.)','<b>He comes.</b> The avatāras say God does not stay far away: he enters the world when it needs him.','<b>Surrender.</b> Gajendra and Bali teach that letting go of pride brings him close.','<b>With Lakṣmī.</b> Abundance and goodness belong together.'],
 [('z','Calm in the middle of action?'),('b','Resting on the snake, Zappy, holding the world.')],'<b>Care</b> that never stops.')],
wfig=row('Conch, discus, tulasī and a lamp',[(conch(),1),(discus(),1),(tulasi(),1),(lamp(),1)],'#e3eaf3',150),
words=[('🌊','Kṣīrasāgara','The ocean of milk where he rests.'),('🐍','Śeṣa','The endless serpent who is his bed.'),('🦅','Garuḍa','The eagle king, his mount.'),('⬇️','Avatāra','A descent of God in a form.'),('🌿','Tulasī','Holy basil, dearest to him.'),('🏛️','Divya Deśam','One of the 108 temples sung by the Āḻvārs.')],wtk=[('z','Avatar means descent!'),('b','God coming down, Zappy.')],
end=['<b>Name.</b> Viṣṇu, “the all-pervading”: Nārāyaṇa, Hari.','<b>Look.</b> Dark blue, four arms: conch, discus, mace, lotus.','<b>Home.</b> Vaikuṇṭha and the milk ocean, on Śeṣa, with Lakṣmī and Garuḍa.','<b>Stories.</b> Vāmana, Gajendra, Madhu–Kaiṭabha, the Viśvarūpa.','<b>Worship.</b> Ekādaśī, tulasī, his thousand names.'],
endnext='Meet his two great avatāras: '+L('/vishnu/krishna/','Kṛṣṇa')+' and '+L('/vishnu/rama/','Rāma')+'.',endk='Who is Viṣṇu',
src=[('Reference:','Wikipedia, “Vishnu” (etymology, Ṛgvedic hymns, iconography, avatāras, traditions).'),('Stories:','Retold from the Bhāgavata Purāṇa, the Devī Māhātmya and the Bhagavad Gītā in our own words.')],
unver='meanings of the four emblems (traditional readings, which vary); avatāra lists (texts differ).',study='Study notes on Viṣṇu.')
